 if(returning){const earliest=new Date(state.checkout.legs[0].flight.ArrivalTime).getTime()+3600000;items=items.filter(f=>new Date(f.DepartureTime).getTime()>=earliest);}
 $('#main').innerHTML=page(returning?'Chọn chuyến về':'Chọn chuyến đi',`${items.length} chuyến phù hợp · ${s.passengers} hành khách · Giờ địa phương tại từng sân bay`,`${returning?`<div class="notice selected-flight"><strong>Chiều đi đã chọn: ${esc(state.checkout.legs[0].flight.FlightNumber)} · ${esc(state.checkout.legs[0].fare.Name)}</strong><span>${esc(state.checkout.legs[0].flight.OriginCode)} → ${esc(state.checkout.legs[0].flight.DestinationCode)} · ${day(state.checkout.legs[0].flight.DepartureTime,state.checkout.legs[0].flight.OriginTimeZone)}</span><button class="small ghost" id="change-outbound">Chọn lại chiều đi</button></div><div class="spacer"></div>`:''}${searchForm()}${afBasicFilters(items)}<div class="stack" id="af-flight-results"></div>`);bindSearch();afBindBasicFilters(items);
