async function bookings(){if(!await requireUser())return;const r=await api('/bookings');$('#main').innerHTML=page('Chuyến đi của tôi','Theo dõi đặt chỗ, thanh toán và vé điện tử.',r.items.length?table(r.items,[['PNR','Mã đặt chỗ'],['FlightNumber','Chuyến bay',(v,x)=>`${esc(v)}${x.ReturnFlightNumber?'<br><small>'+esc(x.ReturnFlightNumber)+'</small>':''}`],['OriginCode','Điểm đi',(v,x)=>`${esc(v)}${x.ReturnFlightNumber?'<br><small>'+esc(x.DestinationCode)+'</small>':''}`],['DestinationCode','Điểm đến',(v,x)=>`${esc(v)}${x.ReturnFlightNumber?'<br><small>'+esc(x.OriginCode)+'</small>':''}`],['DepartureTime','Khởi hành',(v,x)=>`${day(v,x.OriginTimeZone)} ${hour(v,x.OriginTimeZone)}${x.ReturnDepartureTime?'<br><small>'+day(x.ReturnDepartureTime,x.DestinationTimeZone)+' '+hour(x.ReturnDepartureTime,x.DestinationTimeZone)+'</small>':''}`],['TotalAmount','Tổng tiền',money],['Status','Trạng thái',badge],['BookingID','',v=>`<a class="button small secondary" href="#booking/${v}">Chi tiết</a>`]]):empty('Bạn chưa có đặt chỗ nào','Tìm chuyến bay và bắt đầu hành trình đầu tiên.'));}
