 $('#main').innerHTML=page(`Đặt chỗ ${b.PNR}`,`${r.segments?.length===2?'Khứ hồi · ':''}${b.PassengerCount} hành khách`,`${badge(b.Status)}<div class="spacer"></div>${b.Status==='HELD'?`<div class="notice warning no-print">Thời gian giữ ghế còn lại: <span class="countdown" id="countdown"></span>. Thanh toán trước khi hết hạn.</div><div class="spacer"></div>`:''}${r.tickets.map(t=>`<article class="ticket"><div class="ticket-top"><strong>AeroFlow · Vé điện tử${r.segments?.length===2?' · '+(Number(t.SegmentOrder)===2?'Chiều về':'Chiều đi'):''}</strong>${badge(t.Status)}</div><div class="ticket-body"><div class="ticket-route"><div><strong>${esc(t.OriginCode)}</strong><small>${hour(t.DepartureTime,t.OriginTimeZone)} · ${day(t.DepartureTime,t.OriginTimeZone)}</small></div><span>✈ ${esc(t.FlightNumber)}</span><div><strong>${esc(t.DestinationCode)}</strong><small>${hour(t.ArrivalTime,t.DestinationTimeZone)} · ${day(t.ArrivalTime,t.DestinationTimeZone)}</small></div></div><div class="ticket-detail"><div><span>Hành khách</span><b>${esc(t.FullName)}</b></div><div><span>Ghế / Hạng vé</span><b>${esc(t.SeatNumber)} · ${esc(t.FareName)}</b></div><div><span>Hành lý</span><b>${t.BaggageKg} kg</b></div><div><span>Giá vé đã gồm thuế và phí ghế</span><b>${money(t.Amount)}</b></div><div><span>Số vé</span><b>${esc(t.TicketNumber)}</b></div><div><span>Mã đặt chỗ</span><b>${esc(b.PNR)}</b></div><div><span>Giấy tờ (4 ký tự cuối)</span><b>•••• ${esc(t.DocumentLast4)}</b></div><div><span>Hoàn trước ít nhất 24 giờ</span><b>${Number(t.RefundPercent)}%</b></div></div><p class="muted print-only">Vé mô phỏng phục vụ học tập, không sử dụng để lên chuyến bay thực tế.</p></div></article>`).join('')}<div class="card no-print"><div class="total"><span>Tổng đặt chỗ</span><strong>${money(b.TotalAmount)}</strong></div>${b.Status==='HELD'?'<p class="muted">Thanh toán mô phỏng, không cần nhập thông tin thẻ hoặc tài khoản ngân hàng.</p><div class="actions"><button id="pay-success">Mô phỏng thanh toán thành công</button><button id="pay-fail" class="ghost">Mô phỏng thất bại</button></div>':''}<div class="actions">${b.Status==='CONFIRMED'?'<button id="print-ticket" class="secondary">In / Lưu vé PDF</button>':''}${['HELD','CONFIRMED'].includes(b.Status)?'<button id="cancel-booking" class="danger">Hủy đặt chỗ</button>':''}<a class="button ghost" href="#bookings">Lịch sử đặt vé</a></div></div><div class="spacer"></div><section class="no-print"><h2>Lịch sử giao dịch</h2>${r.payments.length?table(r.payments,[['PaymentID','Mã GD'],['Kind','Loại',v=>esc(statuses[v])],['Amount','Số tiền',money],['Status','Kết quả',badge],['CreatedAt','Thời điểm',v=>day(v)+' '+hour(v)]]):empty('Chưa có giao dịch','Thanh toán hoặc hoàn tiền sẽ xuất hiện tại đây.')}</section>`);
